//! Embeds the glyph PNGs as `$OUT_DIR/assets.rs`.
//!
//! The generated file holds `GLYPHS`, sorted by logical path.

use std::fmt::Write as _;
use std::fs;
use std::path::PathBuf;

fn main() {
    let manifest = PathBuf::from(std::env::var("CARGO_MANIFEST_DIR").expect("manifest dir"));
    let root = manifest.join("..");
    let out = PathBuf::from(std::env::var("OUT_DIR").expect("out dir")).join("assets.rs");

    let glyphs_dir = root.join("assets/glyphs");

    let mut glyphs: Vec<(String, u8, PathBuf)> = Vec::new();
    for entry in fs::read_dir(&glyphs_dir).expect("assets/glyphs").flatten() {
        let dir = entry.path();
        if !dir.is_dir() {
            continue;
        }
        let Some(name) = dir.file_name().and_then(|n| n.to_str()) else {
            continue;
        };
        let Ok(digit) = name.parse::<u8>() else {
            continue;
        };
        for file in fs::read_dir(&dir).expect("assets/glyphs/<digit>").flatten() {
            let path = file.path();
            if path.extension().and_then(|e| e.to_str()) != Some("png") {
                continue;
            }
            let logical = format!("glyphs/{name}/{}", file.file_name().to_string_lossy());
            glyphs.push((logical, digit, path));
        }
    }
    glyphs.sort_by(|a, b| a.0.cmp(&b.0));

    let mut generated = String::new();
    generated.push_str("// @generated by build.rs: embedded glyph PNGs.\n");
    generated.push_str("pub static GLYPHS: &[(&str, u8, &[u8])] = &[\n");
    for (logical, digit, path) in &glyphs {
        let _ = writeln!(
            generated,
            "    ({logical:?}, {digit}, include_bytes!({:?})),",
            path.to_string_lossy()
        );
    }
    generated.push_str("];\n");

    fs::write(&out, generated).expect("write assets.rs");
    // Cargo scans a directory given here recursively.
    println!("cargo::rerun-if-changed={}", glyphs_dir.display());
}
